use rand::{prelude::ThreadRng, Rng};
use std::sync::OnceLock;

// Every word accepted as a guess
static WORD_LIST_RAW: &str = include_str!("word-list.txt");
// Common words the answer is picked from (generated by src/scripts/build-answers.py)
static ANSWER_LIST_RAW: &str = include_str!("answers.txt");
static WORD_LIST: OnceLock<Vec<&'static str>> = OnceLock::new();
static ANSWER_LIST: OnceLock<Vec<&'static str>> = OnceLock::new();

fn parse_list(raw: &'static str) -> Vec<&'static str> {
    let mut words: Vec<&str> = raw
        .lines()
        .map(|w| w.trim())
        .filter(|w| w.len() == 5 && w.chars().all(|c| c.is_ascii_lowercase()))
        .collect();
    words.sort_unstable();
    words
}

fn get_word_list() -> &'static Vec<&'static str> {
    WORD_LIST.get_or_init(|| parse_list(WORD_LIST_RAW))
}

fn get_answer_list() -> &'static Vec<&'static str> {
    ANSWER_LIST.get_or_init(|| parse_list(ANSWER_LIST_RAW))
}

pub fn choose_word() -> &'static str {
    /*!
    Returns a random word from the answer list
    */
    let mut rng: ThreadRng = rand::thread_rng();
    let words = get_answer_list();
    let index = rng.gen_range(0..words.len());

    words[index]
}

pub fn word_isvalid(word: &str) -> bool {
    // Check if word is exactly 5 characters and exists in dictionary
    if word.len() != 5 {
        return false;
    }

    // Use binary search on the pre-sorted word list for better performance
    get_word_list().binary_search(&word).is_ok()
}

pub fn get_word_count() -> usize {
    get_word_list().len()
}

pub fn get_answer_count() -> usize {
    get_answer_list().len()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_word_validation() {
        // Test valid words
        assert!(word_isvalid("abaft"));
        assert!(word_isvalid("aback"));

        // Test invalid words
        assert!(!word_isvalid("xyz")); // not in dictionary
        assert!(!word_isvalid("abac")); // too short
        assert!(!word_isvalid("abafts")); // too long
        assert!(!word_isvalid("ABACI")); // wrong case

        // Test partial matches (should not work)
        assert!(!word_isvalid("abaf")); // partial match of "abaft"
    }

    #[test]
    fn test_word_selection() {
        // Test that choose_word returns valid words
        for _ in 0..10 {
            let word = choose_word();
            assert_eq!(word.len(), 5);
            assert!(word_isvalid(word));
        }
    }

    #[test]
    fn test_every_answer_is_a_valid_guess() {
        assert!(get_answer_count() > 1000);
        for answer in get_answer_list() {
            assert!(
                word_isvalid(answer),
                "answer '{}' is not in word-list.txt",
                answer
            );
        }
    }

    #[test]
    fn test_obscure_words_are_guesses_not_answers() {
        assert!(word_isvalid("abaft"));
        assert!(get_answer_list().binary_search(&"abaft").is_err());
    }
}
